-- ============================================================
-- SEED EXT 3: Módulo 02 — Present Simple (ex 181-240)
-- Novos tópicos: PS em escrita acadêmica, presente histórico,
-- verbos estativos avançados, adv. de frequência, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-simple';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-simple não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: present simple em escrita acadêmica
  (cid,31,181,'gap_fill','The present study _____ (examine) the relationship between sleep deprivation and cognitive performance.','examines',NULL,'Present simple = present tense of academic writing (not the past, not the continuous).','medium'),
  (cid,31,182,'multiple_choice','In academic writing, which tense is used for general facts or findings that are still considered valid?','Present simple: "Research shows that regular exercise improves cognitive function."','["Past simple: ''Research showed that exercise improved cognitive function.''","Present perfect: ''Research has shown that exercise has improved cognitive function.''","Present simple: ''Research shows that regular exercise improves cognitive function.''","Present continuous: ''Research is showing that exercise is improving cognitive function.''"]','Present simple for accepted truths, established findings, and academic claims.','medium'),
  (cid,31,183,'gap_fill','This paper _____ (argue) that current urban planning models fail to account for demographic shifts.','argues',NULL,'"This paper argues" = standard academic present simple for the author''s main claim.','easy'),
  (cid,31,184,'multiple_choice','Which sentence uses present simple INCORRECTLY in academic writing?','The authors were demonstrating that access to clean water reduces child mortality rates.','["The data suggest a significant correlation between income and health outcomes.","This study addresses a gap in the existing literature.","The authors were demonstrating that access to clean water reduces child mortality rates.","The findings indicate that the hypothesis requires revision."]','"Were demonstrating" = incorrect in academic writing. Use "demonstrate" (present simple).','medium'),
  (cid,31,185,'gap_fill','The results _____ (indicate) that the treatment group _____ (show) statistically significant improvement.','indicate / shows',NULL,'Present simple for reporting current results in academic writing.','easy'),

  -- BLOCK 32: presente histórico (historical present)
  (cid,32,186,'gap_fill','In his 1776 treatise, Adam Smith _____ (argue) that the division of labor is the primary source of economic growth.','argues',NULL,'Historical present: authors still ''argue'' in their works — the text remains active.','medium'),
  (cid,32,187,'multiple_choice','Why is present simple used in: "Shakespeare writes in Hamlet that to be or not to be is the fundamental human question"?','The literary text exists as a permanent artifact — the author perpetually "writes" in it.','["Shakespeare is alive and still writing","The sentence is informal","The literary text exists as a permanent artifact — the author perpetually ''writes'' in it.","It is an error — past simple is required"]','Historical/literary present: authors speak perpetually through their texts.','hard'),
  (cid,32,188,'gap_fill','Darwin _____ (observe) in On the Origin of Species that species with advantageous traits _____ (survive) longer.','observes / survive',NULL,'Historical/literary present for referencing what an author says in a published work.','medium'),
  (cid,32,189,'multiple_choice','Which is correct in an academic literature review?','Foucault argues that power operates through institutions rather than individuals.','["Foucault argued that power operated through institutions rather than individuals (past simple — acceptable but less common in literary/philosophical analysis).","Foucault was arguing that power operated through institutions.","Foucault argues that power operates through institutions rather than individuals.","Foucault has argued that power will operate through institutions."]','Literary present preferred in academic writing: "Foucault argues" (still valid claim).','hard'),

  -- BLOCK 33: verbos estativos avançados no PS
  (cid,33,190,'gap_fill','The study _____ (contain) several significant methodological limitations that _____ (affect) the validity of its conclusions.','contains / affect',NULL,'"Contain" and "affect" = stative and dynamic verbs both use present simple for general statements.','medium'),
  (cid,33,191,'multiple_choice','Which stative verb is INCORRECTLY used in continuous form in this academic sentence?','The data appears consistent with previous findings.','["The data appears consistent with previous findings.","The argument lacks empirical support.","The model is involving several assumptions that may not hold.","The results depend on the initial conditions."]','"Involving" = incorrect. "Involve" is stative → "is involving" should be "involves."','hard'),
  (cid,33,192,'gap_fill','The correlation coefficient _____ (represent) the strength of the linear relationship between the two variables.','represents',NULL,'"Represent" = stative verb for definition/function — present simple.','easy'),
  (cid,33,193,'multiple_choice','Which sentence uses "include" vs "comprise" correctly?','The sample includes participants from five countries. The study comprises four distinct phases.','["The sample is including participants from five countries.","The sample includes participants from five countries. The study comprises four distinct phases.","The study is comprising four phases.","The sample includes, and the study is comprising, four phases."]','"Include" and "comprise" = stative verbs. No continuous form.','medium'),

  -- BLOCK 34: adv. de frequência em contexto acadêmico
  (cid,34,194,'gap_fill','Researchers _____ (typically/use) mixed-methods approaches when studying complex social phenomena.','typically use',NULL,'"Typically" = frequency adverb in academic generalizations. Present simple.','easy'),
  (cid,34,195,'multiple_choice','Where does a frequency adverb go in: "High-income countries _____ adopt new technologies _____ faster than low-income countries"?','High-income countries typically adopt new technologies faster.','["High-income countries adopt typically new technologies faster.","High-income countries typically adopt new technologies faster.","Typically, high-income countries adopt new technologies faster (sentence initial — also acceptable).","High-income countries adopt new technologies typically faster."]','Frequency adverbs precede main verbs; sentence-initial position with comma also accepted.','hard'),
  (cid,34,196,'gap_fill','Viral mutations _____ (frequently/occur) at regions of the genome that _____ (undergo) high replication pressure.','frequently occur / undergo',NULL,'"Frequently occur" = frequency adverb + present simple for scientific generalizations.','medium'),
  (cid,34,197,'multiple_choice','Which pair of frequency adverbs is ranked correctly (most → least frequent)?','Always > usually > often > sometimes > rarely > never.','["Often > always > sometimes > rarely","Always > usually > often > sometimes > rarely > never.","Usually > sometimes > often > always","Rarely > sometimes > often > usually > always"]','Standard frequency order: always (100%) → never (0%).','easy'),

  -- BLOCK 35: TOEFL Reading
  (cid,35,198,'multiple_choice','[TOEFL Reading] "Iron deficiency impairs cognitive development in young children, according to numerous longitudinal studies." Why present simple?','It states a well-established, scientifically accepted fact.','["It describes a specific past event","The author is uncertain about the fact","It states a well-established, scientifically accepted fact.","The reading was written in the present moment"]','Present simple for established scientific truths.','easy'),
  (cid,35,199,'gap_fill','[TOEFL Reading] "The article _____ (demonstrate) that renewable energy sources _____ (have) become economically competitive with fossil fuels in most markets." Best form?','demonstrates / have',NULL,'"Demonstrates" (present simple for author''s claim) + "have become" (present perfect for recent change).','hard'),
  (cid,35,200,'multiple_choice','[TOEFL Reading] "In his 1962 work, Kuhn describes scientific progress as a series of paradigm shifts rather than linear accumulation." "Describes" is in present tense because:','The text is permanent — Kuhn perpetually "describes" in his published work.','["Kuhn is still alive","The fact is not yet accepted","The text is permanent — Kuhn perpetually ''describes'' in his published work.","The reading is about the present"]','Literary/historical present: published works use present simple.','medium'),
  (cid,35,201,'gap_fill','[TOEFL Reading] "The evidence _____ (suggest) a causal link, though further investigation _____ (remain) necessary." Best forms?','suggests / remains',NULL,'Present simple for current evidence and ongoing requirement.','easy'),

  -- BLOCK 36: TOEFL Speaking
  (cid,36,202,'production','[TOEFL Speaking — 45s] A reading discusses the relationship between poverty and health outcomes. Summarize using academic present simple, frequency adverbs, and stative verbs.','',NULL,'The reading demonstrates that poverty and poor health outcomes are strongly correlated across all demographic groups studied. Research consistently shows that individuals with lower incomes typically have limited access to preventive healthcare, nutritious food, and safe housing. The data suggests a clear causal direction: material deprivation impairs both physical and mental health through multiple mechanisms. Studies frequently indicate that early interventions — particularly in early childhood — significantly reduce the long-term health burden associated with socioeconomic disadvantage. The authors argue that addressing poverty therefore constitutes a public health imperative, not merely an economic or moral one.','hard'),
  (cid,36,203,'production','[TOEFL Speaking — 45s] Describe your academic or career goals. Use: present simple for facts/plans, frequency adverbs, stative verbs, and literary present (e.g., a book or author that influenced you).','',NULL,'My academic goal is to pursue a doctoral degree in environmental policy, a field that increasingly demands both scientific literacy and policy expertise. I typically spend several hours each week reading current research on climate adaptation and urban resilience. I find the work of political scientist Elinor Ostrom particularly relevant — she demonstrates in Governing the Commons that communities often manage shared resources more sustainably than either markets or governments. Her research challenges the conventional wisdom that privatization always improves outcomes. I believe that combining rigorous quantitative analysis with deep community engagement represents the most effective approach to the challenges my generation inherits.','hard'),

  -- BLOCK 37: TOEFL Writing
  (cid,37,204,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "The role of diet in chronic disease prevention." Use: present simple (×5 minimum), frequency adverbs (×2), stative verbs (appear/contain/represent/suggest), literary present for a researcher, and passive present simple (×1).','',NULL,'A substantial body of epidemiological research indicates that dietary patterns are among the most powerful modifiable determinants of chronic disease risk. Diets rich in whole grains, legumes, and vegetables consistently appear to be associated with lower rates of cardiovascular disease, type 2 diabetes, and certain cancers. Conversely, diets high in ultra-processed foods typically contain elevated levels of sodium, refined sugars, and saturated fats, which collectively represent significant risk factors for metabolic syndrome. Extensive longitudinal data from studies spanning several decades suggest that even modest dietary improvements — replacing refined grains with whole grains, for instance — produce measurable health benefits at the population level. The epidemiologist David Katz argues in his synthesis of the evidence that the fundamentals of a health-promoting diet are broadly agreed upon, despite the persistent proliferation of conflicting nutritional advice in popular media.','hard'),
  (cid,37,205,'production','[TOEFL Writing — Error Correction] Fix present simple errors: "This paper is examining three key arguments. Darwin was arguing in Origin of Species that evolution proceeds gradually. Research are showing consistent patterns. The model is representing three core assumptions. Typically, researchers are using large sample sizes to ensure validity."','',NULL,'is examining → examines (academic writing uses present simple, not continuous, for the paper''s content); was arguing → argues (literary/historical present — the text is permanent); Research are → Research shows (''research'' = uncountable → singular verb, present simple); is representing → represents (represent = stative verb → no continuous); are using → use or typically use (stative/habitual context in academic generalization → present simple).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
